import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-admission-diagnostic-');
const driver="tests/infrastructure/database/projected-writer.test.ts",paths=["tests/infrastructure/database/projected-writer.test.ts","src/infrastructure/database/projection-recovery.ts","src/infrastructure/database/projection-source.ts","src/infrastructure/database/projection-replacement.ts","src/infrastructure/database/event-log.ts","src/application/services/memory-governance-service.ts","src/application/services/dreaming-service.ts","src/presentation/cli/commands/governance.ts","src/presentation/cli/commands/dream.ts"];
const tests=[driver];
const mode=process.argv[2]??'measure';if(!['measure','faults'].includes(mode))throw Error('Invalid mode');
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content.replace(/from "commander"/g, "from "+JSON.stringify(Bun.resolveSync("commander",root))));}
const runs:any[]=[];
try{
 for(const path of tests.slice(1))put(path,readFileSync(path,'utf8'));
 for(const path of [...tests,...paths])for(const match of readFileSync(path,'utf8').matchAll(/from ["'](\.[^"']+)["']/g)){
 const target=resolve(dirname(path),match[1]).replace(/\.js$/,'.ts');const local=target.slice(root.length+1).replaceAll('\\','/');
 if(!paths.includes(local)&&!tests.includes(local))put(local,'export * from '+JSON.stringify(target.replaceAll('\\','/'))+';');
}
 put('capture.ts','import {afterAll} from "bun:test";import {writeFileSync} from "node:fs";afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+(mode==='measure'?',"./capture.ts"':'')+']\n');
 const faults=mode==='faults'?[{"path":"src/infrastructure/database/projection-source.ts","kind":"accept-truncated-history","from":"candidate.bytes < file.bytes","to":"false"},{"path":"src/infrastructure/database/projection-source.ts","kind":"accept-rewritten-history","from":"hash.digest(\"hex\") !== file.sha256) throw","to":"false) throw"},{"path":"src/infrastructure/database/projection-replacement.ts","kind":"omit-append-only-enforcement","from":"assertProjectionSourceAuthority(db, source, automatic)","to":"assertProjectionSourceAuthority(db, source)"},{"path":"src/infrastructure/database/projection-recovery.ts","kind":"ignore-missing-acknowledged-source","from":"if (hasReceipt(db)) throw","to":"if (false) throw"},{"path":"src/application/services/memory-governance-service.ts","kind":"reapply-after-projected-writer","from":"written?.projectionCommitted","to":"false"},{"path":"src/application/services/dreaming-service.ts","kind":"reject-completed-apply-retry","from":"entry.status === \"applied\"","to":"false"},{"path":"src/application/services/dreaming-service.ts","kind":"reject-completed-rollback-retry","from":"entry.status === \"rolled_back\"","to":"false"},{"path":"src/presentation/cli/commands/governance.ts","kind":"ignore-known-pending-recovery","from":"(await recoverPendingProjections(db, deps.eventLogPath)).pending","to":"(await recoverPendingProjections(db, deps.eventLogPath),false)"}]:[];
 for(const fault of [null,...faults]){
  for(const [path,content]of originals)put(path,mode==='measure'?instrumentTypeScriptWithCoverage(content,resolve(path)).code:content);
  if(fault){const content=originals.get(fault.path)!;if('from' in fault){if(!content.includes(fault.from))throw Error('Missing mutation '+fault.kind);put(fault.path,content.replaceAll(fault.from,fault.to));}else put(fault.path,content.slice(0,fault.offset)+'const'+content.slice(fault.offset+5));}
  const command=[process.execPath,'test','--timeout','15000',...(mode==='measure'?tests:[driver])];
  const child=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:90000});
  const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);
  runs.push({fault,command,exit:child.exitCode,output});
  writeFileSync('.git/q100-writer-diagnostic-progress.json',JSON.stringify({runs},null,2));
  if(!fault && child.exitCode!==0)throw Error('Control run failed\n'+output);
  if(fault && child.exitCode!==0 && !output.includes('(fail)'))throw Error('Mutation did not reach assertions\n'+output);
 }
 let measurement:unknown;
 if(mode==='measure'){
  const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
  const files=paths.map(path=>{const measured=map.fileCoverageFor(resolve(path)),data=measured.data;return{path,sourceHash:sourceHash(originals.get(path)!),metrics:measured.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};});
  measurement={files,rawCoverage:raw};console.log(JSON.stringify(files));
 }else console.log(JSON.stringify(runs.map(run=>({fault:run.fault,exit:run.exit}))));
 writeFileSync(`.git/q100-writer-${mode}.json`,JSON.stringify({recordedAt:new Date().toISOString(),scope:'Scoped diagnostic; full instrumenter/platform/package/changed-line and independent review acceptance remains open.',runtime:Bun.version,sourceInputs:paths.map(path=>({path,sourceHash:sourceHash(originals.get(path)!)})),runs,measurement,source:readFileSync('.git/q100-writer-diagnostic.ts','utf8')},null,2)+'\n');
}finally{storage.cleanup();}

